$nodeScript = @'
const fs = require('fs')
const { PNG } = require('pngjs')
const pixelmatch = require('pixelmatch')
const reference = PNG.sync.read(fs.readFileSync('D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/home-v2/fixtures/navbar-reference.png'))
const baseline = PNG.sync.read(fs.readFileSync('C:/Users/Administrator/.dsh/attachments/v1/objects/3a/3a11aed43af6bbd863f34916990b7d839fbf3570f4af9c5015071b7346142dde'))
const sprite = PNG.sync.read(fs.readFileSync('D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/artifacts/task2468-navbar-visual/navbar-visual-1920.png'))
const items = [['工作中心',514],['数据大屏',653],['行业管理',779],['项目管理',905],['业主自治',1031],['共有资金',1157],['阳光物业',1283],['公共查询',1409],['设施设备',1535],['公共信息',1661]]
function crop(img, x, y, w, h) {
  const out = Buffer.alloc(w * h * 4)
  for (let row=0; row<h; row++) img.data.copy(out,row*w*4,((y+row)*img.width+x)*4,((y+row)*img.width+x+w)*4)
  return out
}
for (const [title, center] of items) {
  const x = center - 18, y = 18, w = 36, h = 42
  const target = crop(reference,x,y,w,h)
  const baseRate = 1 - pixelmatch(crop(baseline,x,y,w,h),target,null,w,h,{threshold:0.1,includeAA:false})/(w*h)
  const spriteRate = 1 - pixelmatch(crop(sprite,x,y,w,h),target,null,w,h,{threshold:0.1,includeAA:false})/(w*h)
  console.log(`${title}: Element=${(baseRate*100).toFixed(1)}%, sprite=${(spriteRate*100).toFixed(1)}%, delta=${((spriteRate-baseRate)*100).toFixed(1)}pp`)
}
'@
node -e $nodeScript
